package me.theoria.wifimuscles.model;

import android.content.Context;
import android.widget.TextView;

import com.github.mikephil.charting.components.MarkerView;
import com.github.mikephil.charting.data.Entry;
import com.github.mikephil.charting.highlight.Highlight;
import com.github.mikephil.charting.utils.MPPointF;

import me.theoria.wifimuscles.R;

public class ChartMarkerModel extends MarkerView {

    private final TextView markerContent;

    public ChartMarkerModel(Context context, int layoutResource) {
        super(context, layoutResource);
        markerContent = findViewById(R.id.markerContent);
    }

    @Override
    public void refreshContent(Entry e, Highlight highlight) {
        if (e != null) {
            float rssi = e.getY();
            RSSILevelModel level = RSSILevelModel.mapRssi(rssi);
            String rssiMarker = (int) rssi + " dBm | " + level;
            markerContent.setText(rssiMarker);
        }
        super.refreshContent(e, highlight);
    }

    @Override
    public MPPointF getOffset() {
        return new MPPointF(-(getWidth() / 3f), -getHeight());
    }
}

package me.theoria.wifimuscles.model.repo;

import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;

import java.util.List;

import me.theoria.wifimuscles.data.model.WifiSignalModel;
import me.theoria.wifimuscles.data.managers.SignalProcessManager;
import me.theoria.wifimuscles.viewmodel.DataUIViewModel;

public class ChartManager {

    private final SignalProcessor signalProcessManager;
    private final DataUIViewModel uiUpdater;

    public ChartManager(SignalProcessor signalProcessManager, DataUIViewModel uiUpdater) {
        this.signalProcessManager = signalProcessManager;
        this.uiUpdater = uiUpdater;
    }

    public void updateChart(
            List<WifiSignalModel> signals,
            LineChart chart,
            LineDataSet rssiDataSet,
            LineDataSet excellentSet,
            LineDataSet goodSet,
            LineDataSet fairSet,
            LineDataSet weakSet,
            LineDataSet unusableSet,
            LineData lineData
    ) {
        if (chart == null || rssiDataSet == null || lineData == null) return;

        // Clear datasets
        clearAllDataSets(rssiDataSet, excellentSet, goodSet, fairSet, weakSet, unusableSet);

        // Process signals and update UI
        signalProcessManager.processSignals(signals, rssiDataSet, excellentSet, goodSet, fairSet, weakSet, unusableSet);

        if (uiUpdater != null) {
            uiUpdater.updateSignalUI(signals);
        }

        // Notify chart update
        notifyChartUpdated(chart, lineData, rssiDataSet, excellentSet, goodSet, fairSet, weakSet, unusableSet);
    }

    private void clearAllDataSets(LineDataSet... sets) {
        for (LineDataSet set : sets) {
            set.clear();
        }
    }

    private void notifyChartUpdated(
            LineChart chart,
            LineData lineData,
            LineDataSet... sets
    ) {
        for (LineDataSet set : sets) {
            set.notifyDataSetChanged();
        }

        lineData.notifyDataChanged();
        chart.notifyDataSetChanged();
        chart.invalidate();
        chart.setVisibleXRangeMaximum(30);
        chart.moveViewToX(lineData.getEntryCount());
    }
}

package me.theoria.wifimuscles.model;

import androidx.annotation.DrawableRes;
import androidx.annotation.StringRes;

import me.theoria.wifimuscles.R;

public enum RSSILevelModel {

    // Bind RSSI String levels to drawables that fill under the line
    EXCELLENT(R.string.label_excellent, R.drawable.fill_blue), // 0 to -50
    GOOD(R.string.label_good, R.drawable.fill_green), // -50 to -70
    FAIR(R.string.label_fair, R.drawable.fill_yellow), // -70 to -80
    WEAK(R.string.label_weak, R.drawable.fill_red), // -80 to -90
    UNUSABLE(R.string.label_unusable, R.drawable.fill_red); // < -90

    @StringRes
    private final int wifiStrengthLabel;
    @DrawableRes
    private final int fillDrawableRes;

    RSSILevelModel(@StringRes int wifiStrengthLabel, @DrawableRes int fillDrawableRes) {
        this.wifiStrengthLabel = wifiStrengthLabel;
        this.fillDrawableRes = fillDrawableRes;
    }

    public int getRssiLabel() {
        return wifiStrengthLabel;
    }

    public int getFillDrawableRes() {
        return fillDrawableRes;
    }

    // Maps RSSI float to String levels that are displayed on the chart instead
    public static RSSILevelModel mapRssi (float rssi) {
        if (rssi >= -50) {
            return EXCELLENT;
        } else if (rssi >= -60) {
            return GOOD;
        } else if (rssi >= -70) {
            return FAIR;
        } else if (rssi >= -80) {
            return WEAK;
        } else {
            return UNUSABLE;
        }
    }
}

package me.theoria.wifimuscles.model;

public class WifiSignalModel {
    private final long timestamp;
    private final int rssi, signalLevel, frequency, ip, networkID;

    public WifiSignalModel(long timestamp, int rssi, int signalLevel, int frequency, int ip, int networkID) {
        this.timestamp = timestamp;
        this.rssi = rssi;
        this.signalLevel = signalLevel;
        this.frequency = frequency;
        this.ip = ip;
        this.networkID = networkID;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public int getRssi() {
        return rssi;
    }

    public int getSignalLevel() {
        return signalLevel;
    }

    public int getIP() { return ip; }

    public int getFrequency() { return frequency; }

    public int getNetworkID() { return networkID; }
}

package me.theoria.wifimuscles.utils;

import android.content.Context;
import android.graphics.Color;
import android.graphics.Typeface;

import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.components.Description;
import com.github.mikephil.charting.components.XAxis;
import com.github.mikephil.charting.components.YAxis;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;
import com.github.mikephil.charting.formatter.ValueFormatter;

import java.util.ArrayList;

import me.theoria.wifimuscles.R;
import me.theoria.wifimuscles.data.model.ChartMarkerModel;
import me.theoria.wifimuscles.data.model.RSSILevelModel;

public class ChartConfig {

    public static class ChartSetupResult {
        public LineChart chart;
        public LineDataSet primaryDataSet, excellentSet, goodSet, fairSet, weakSet, unusableSet;
        public LineData lineData;
    }

    public static ChartSetupResult setupChartConfig(LineChart chart, Context context) {

        configureChart(chart);
        configureXAxis(chart.getXAxis());
        configureYAxis(chart.getAxisLeft());
        chart.getAxisRight().setEnabled(false);

        LineDataSet rssiValueDataSet = createPrimaryDataSet(context);
        setMarkerView(chart, context);

        LineDataSet excellentSet = createLineThresholdDataSet(context, RSSILevelModel.EXCELLENT);
        LineDataSet goodSet = createLineThresholdDataSet(context, RSSILevelModel.GOOD);
        LineDataSet fairSet = createLineThresholdDataSet(context, RSSILevelModel.FAIR);
        LineDataSet weakSet = createLineThresholdDataSet(context, RSSILevelModel.WEAK);
        LineDataSet unusableSet = createLineThresholdDataSet(context, RSSILevelModel.UNUSABLE);

        LineData lineData = new LineData();
        lineData.addDataSet(rssiValueDataSet);

        // Currently empty datasets
        /*lineData.addDataSet(excellentSet);
        lineData.addDataSet(goodSet);
        lineData.addDataSet(fairSet);
        lineData.addDataSet(weakSet);
        lineData.addDataSet(unusableSet);*/

        chart.setData(lineData);
        chart.invalidate();

        ChartSetupResult result = new ChartSetupResult();
        result.chart = chart;
        result.primaryDataSet = rssiValueDataSet;
        result.excellentSet = excellentSet;
        result.goodSet = goodSet;
        result.fairSet = fairSet;
        result.weakSet = weakSet;
        result.unusableSet = unusableSet;
        result.lineData = lineData;

        return result;
    }

    private static void configureChart(LineChart chart) {
        chart.setDrawGridBackground(false);
        chart.setBackgroundColor(Color.TRANSPARENT);
        chart.setTouchEnabled(true);
        chart.setDragEnabled(true);
        chart.setScaleEnabled(true);
        chart.setExtraBottomOffset(10f);
        chart.setExtraTopOffset(10f);
        chart.setExtraLeftOffset(5f);
        chart.getLegend().setEnabled(false);

        // Remove the description label
        Description description = new Description();
        description.setEnabled(false); // Disable the description
        chart.setDescription(description);
    }

    private static void configureXAxis(XAxis xAxis) {
        xAxis.setPosition(XAxis.XAxisPosition.BOTTOM);
        xAxis.setDrawGridLines(true);
        xAxis.setDrawLabels(false);
        xAxis.setDrawAxisLine(false);
        xAxis.setGranularity(5f);
        xAxis.setGranularityEnabled(true);
        xAxis.setLabelCount(8, false);
        xAxis.setTextColor(R.color.bg_secondary);
    }

    private static void configureYAxis(YAxis yAxis) {
        yAxis.setDrawGridLines(false);
        yAxis.setPosition(YAxis.YAxisLabelPosition.OUTSIDE_CHART);
        yAxis.setYOffset(0f);
        yAxis.setXOffset(0f);
        yAxis.setAxisMinimum(-100f); // dBm
        yAxis.setAxisMaximum(0f);
        yAxis.setGranularity(10f);
        yAxis.setLabelCount(5, true);
        yAxis.setTextSize(12f);
        yAxis.setDrawLabels(false);
        yAxis.setTypeface(Typeface.defaultFromStyle(Typeface.BOLD));
        yAxis.setValueFormatter(new ValueFormatter() {
            @Override
            public String getFormattedValue(float value) {
                return ((int) value) + " dBm";
            }
        });
    }

    private static LineDataSet createPrimaryDataSet(Context context) {
        LineDataSet dataSet = new LineDataSet(new ArrayList<>(), context.getString(R.string.label_blank));
        dataSet.setDrawCircles(false);
        dataSet.setDrawValues(false);
        dataSet.setMode(LineDataSet.Mode.CUBIC_BEZIER);
        dataSet.setCubicIntensity(0.3f);
        dataSet.setColor(context.getColor(R.color.accent_orange));
        dataSet.setLineWidth(2f);
        dataSet.setDrawFilled(false);
        dataSet.setDrawCircleHole(true);
        dataSet.getColor(R.color.accent_pink);
        //dataSet.setFillColor(Color.parseColor("#05DA93")); // Solid fill
        return dataSet;
    }

    private static void setMarkerView(LineChart chart, Context context) {
        ChartMarkerModel marker = new ChartMarkerModel(context, R.layout.marker_rssi);
        marker.setChartView(chart);
        chart.setMarker(marker);
    }

    private static LineDataSet createLineThresholdDataSet(Context context, RSSILevelModel level) {
        LineDataSet set = new LineDataSet(new ArrayList<>(), context.getString(level.getRssiLabel()));
        set.setColor(R.color.accent_pink);
        set.setMode(LineDataSet.Mode.CUBIC_BEZIER);
        set.setLineWidth(3.5f);
        set.setDrawCircles(true);
        set.setDrawValues(false);
        set.setDrawFilled(false);
        return set;
    }
}

package me.theoria.wifimuscles.utils;

public class IntoToString {

    public static String intToIp(int ip) {
        return (ip & 0xFF) + "." +
                ((ip >> 8) & 0xFF) + "." +
                ((ip >> 16) & 0xFF) + "." +
                ((ip >> 24) & 0xFF);
    }

}

package me.theoria.wifimuscles.utils;

import me.theoria.wifimuscles.R;

public class RSSIUtils {

    /**
     * Method: mapRssiToLevels
     * This method takes the rssi reading and simplifies it to a one through five scale.
     * @param rssi
     * @return
     */
    public static Integer mapRssiToLevels(int rssi) {
        return rssi;
    }

    /**
     * Method: getRssiEmoji
     * This method takes the rssi reading and displays an emoji based on a one through five scale.
     * @param rssi
     * @return
     */
    public static int getRssiEmoji(int rssi) {
        if (rssi >= -30) {
            return R.drawable.emoji_mood_very_satisfied_24;
        } else if (rssi >= -50) {
            return R.drawable.emoji_mood_satisfied_24;
        } else if (rssi >= -70){
            return R.drawable.emoji_mood_neutral_24;
        } else if (rssi >= -90) {
            return R.drawable.emoji_mood_dissatisfied_24;
        } else return R.drawable.emoji_mood_bad_24;
    }
}

package me.theoria.wifimuscles.utils;

import com.github.mikephil.charting.data.Entry;
import com.github.mikephil.charting.data.LineDataSet;
import me.theoria.wifimuscles.data.model.RSSILevelModel;
import me.theoria.wifimuscles.data.model.WifiSignalModel;

import java.util.List;

public class SignalProcessor {

    public void processSignals(
            List<WifiSignalModel> signals,
            LineDataSet rssiDataSet,
            LineDataSet excellentSet,
            LineDataSet goodSet,
            LineDataSet fairSet,
            LineDataSet weakSet,
            LineDataSet unusableSet
    ) {
        for (int i = 0; i < signals.size(); i++) {
            WifiSignalModel signal = signals.get(i);
            int rssi = signal.getRssi();
            float rssiFloat = signal.getRssi();

            // Process each signal and map it to its appropriate level
            RSSILevelModel rssiLevelModel = RSSILevelModel.mapRssi(rssiFloat);
            int signalLevel = RSSIUtils.mapRssiToLevels(rssi);

            // Add entry to the appropriate dataset
            addEntryToDataSets(i, signalLevel, rssiLevelModel, rssiDataSet, excellentSet, goodSet, fairSet, weakSet, unusableSet);
        }
    }

    private void addEntryToDataSets(
            int index,
            int signalLevel,
            RSSILevelModel levelModel,
            LineDataSet rssiDataSet,
            LineDataSet excellentSet,
            LineDataSet goodSet,
            LineDataSet fairSet,
            LineDataSet weakSet,
            LineDataSet unusableSet
    ) {
        Entry entry = new Entry(index, signalLevel);

        if (levelModel != null) {
            switch (levelModel) {
                case EXCELLENT:
                    excellentSet.addEntry(entry);
                    break;
                case GOOD:
                    goodSet.addEntry(entry);
                    break;
                case FAIR:
                    fairSet.addEntry(entry);
                    break;
                case WEAK:
                    weakSet.addEntry(entry);
                    break;
                case UNUSABLE:
                    unusableSet.addEntry(entry);
                    break;
            }
        }

        rssiDataSet.addEntry(entry);
    }
}

package me.theoria.wifimuscles.utils;

import android.content.Context;
import android.widget.Toast;

public class ToastUtil {

    public static void showToast(Context context, String message) {
        Toast.makeText(context, message, Toast.LENGTH_SHORT).show();
    }

    public static void showLongToast(Context context, String message) {
        Toast.makeText(context, message, Toast.LENGTH_LONG).show();
    }

    public static void showToastForLevel(Context context, int level) {
        String message = "";
        switch (level) {
            case 5:
                message = "Excellent coverage!";
                break;
            case 4:
                message = "Good coverage!";
                break;
            case 3:
                message = "Consider placing an extender here!";
                break;
            case 2:
                message = "Add an extender slightly closer to the router!";
                break;
            case 1:
                message = "Unusable WiFi reception!";
                break;
        }
        showToast(context, message);
    }
}

package me.theoria.wifimuscles.view.activities;

import android.Manifest;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Bundle;

import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;


import com.google.android.gms.ads.AdRequest;
import com.google.android.gms.ads.AdView;
import com.google.android.gms.ads.MobileAds;
import com.google.android.material.bottomnavigation.BottomNavigationView;

import me.theoria.wifimuscles.R;
import me.theoria.wifimuscles.view.fragments.ChartFragment;
import me.theoria.wifimuscles.view.fragments.DonateFragment;
import me.theoria.wifimuscles.view.fragments.HomeFragment;
import me.theoria.wifimuscles.view.fragments.RadarChartFragment;

public class MainActivity extends AppCompatActivity {


    @Override
    protected void onCreate(Bundle savedInstanceState) {

        if (ContextCompat.checkSelfPermission(this,
                Manifest.permission.ACCESS_FINE_LOCATION)
                != PackageManager.PERMISSION_GRANTED) {
                ActivityCompat.requestPermissions(
                        this, new String[]{Manifest.permission.ACCESS_FINE_LOCATION}, 1);
        }

        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);


        /**
         * Navigation methods for setting the current fragment, movement between fragments and
         * initializing them on the MainActivity.
         * TODO: Move into NavigationComponent
         */

        // Fragment declaration
        Fragment homeFragment = new HomeFragment();
        Fragment comboWifiFragment = new ChartFragment();
        Fragment secondChartFragment = new RadarChartFragment();
        Fragment donateFragment = new DonateFragment();

        // Set current fragment from setCurrentFragment
        setCurrentFragment(comboWifiFragment);
        // Initialize bottom navigation
        BottomNavigationView bottomNavigationView = findViewById(R.id.bottom_navigation);
        // Bottom navigation logic
        bottomNavigationView.setOnItemSelectedListener(item -> {
            int itemId = item.getItemId();
            if (itemId == R.id.comboChart) {
                setCurrentFragment(comboWifiFragment);
            } else if (itemId == R.id.radarChart) {
                setCurrentFragment(secondChartFragment);
            } else if (itemId == R.id.donate) {
                findViewById(R.id.donate).setOnClickListener(v -> {
                    String paypalDonationUrl = "https://www.paypal.com/ncp/payment/T62DKS2TW4GRN";
                    Intent browserIntent = new Intent(Intent.ACTION_VIEW, Uri.parse(paypalDonationUrl));
                    startActivity(browserIntent);
                });
            }
            return true;
        });

        /**
         * Implement and initialize Google AdMob
         */
        // Initialize Mobile Ads SDK
        MobileAds.initialize(this, initializationStatus -> {});

        // Reference AdView and load ad
        AdView mAdView = findViewById(R.id.adView);
        AdRequest adRequest = new AdRequest.Builder().build();
        mAdView.loadAd(adRequest);
    }

    /**
     * Method: setCurrentFragment
     * Description: Replaces the fragment within the fragment container block from
     * the main activity.
     * @param fragment
     */
    private void setCurrentFragment(Fragment fragment) {
        getSupportFragmentManager()
                .beginTransaction()
                .replace(R.id.fragment_container, fragment)
                .commit();
    }
}

package me.theoria.wifimuscles.view.fragments;

import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.fragment.app.Fragment;
import androidx.lifecycle.ViewModelProvider;

import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;

import me.theoria.wifimuscles.databinding.FragmentChartBinding;
import me.theoria.wifimuscles.data.managers.ChartManager;
import me.theoria.wifimuscles.data.managers.ChartBuilderManager;
import me.theoria.wifimuscles.data.managers.SignalProcessManager;
import me.theoria.wifimuscles.viewmodel.DataUIViewModel;
import me.theoria.wifimuscles.viewmodel.WifiViewModel;

/**
 * ChartFragment inflates the primary chart fragment and observes for LiveData updates.
 */
public class ChartFragment extends Fragment {

    private TextView frequencyTextView, bandwidthTextView, ipTextView, rssiTextView;
    private ImageView rssiEmojiView;
    private LineChart chart;
    private LineDataSet primaryLineDataSet;
    private LineDataSet excellentSet, goodSet, fairSet, weakSet, unusableSet;
    private LineData lineData;

    private DataUIViewModel dataUIViewModel;
    private WifiViewModel wifiViewModel;

    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        FragmentChartBinding binding = FragmentChartBinding.inflate(inflater, container, false);

        // Initialize ViewModels
        wifiViewModel = new ViewModelProvider(this).get(WifiViewModel.class);
        dataUIViewModel = new ViewModelProvider(this).get(DataUIViewModel.class);

        // Initialize chart UI elements
        initChartUI(binding);

        // Setup chart
        setupMainChart();

        // Observe LiveData from both ViewModels
        observeSignalData();
        observeSignalUI();

        return binding.getRoot();
    }

    private void initChartUI(FragmentChartBinding binding) {
        chart = binding.lineChart;
        rssiTextView = binding.rssiTextView;
        rssiEmojiView = binding.rssiEmoji;
        frequencyTextView = binding.frequencyBox;
        bandwidthTextView = binding.bandBox;
        ipTextView = binding.ipTextView;
    }

    private void setupMainChart() {
        ChartConfig.ChartSetupResult chartResults = ChartConfig.setupChartConfig(chart, requireContext());

        primaryLineDataSet = chartResults.primaryDataSet;
        excellentSet = chartResults.excellentSet;
        goodSet = chartResults.goodSet;
        fairSet = chartResults.fairSet;
        weakSet = chartResults.weakSet;
        unusableSet = chartResults.unusableSet;
        lineData = chartResults.lineData;

        chart.setData(lineData);
        chart.invalidate();
    }

    private void observeSignalData() {
        wifiViewModel.getRssiLiveData().observe(getViewLifecycleOwner(), signals -> {
            if (signals == null) return;

            // Update chart only
            ChartManager chartManager = new ChartManager(
                    new SignalProcessor(),
                    null // UI updates are now handled by the ViewModel
            );
            chartManager.updateChart(
                    signals,
                    chart,
                    primaryLineDataSet,
                    excellentSet,
                    goodSet,
                    fairSet,
                    weakSet,
                    unusableSet,
                    lineData
            );

            // Update UI state in the ViewModel
            dataUIViewModel.updateSignalUI(signals);
        });
    }

    private void observeSignalUI() {
        dataUIViewModel.getRssiText().observe(getViewLifecycleOwner(), text -> rssiTextView.setText(text));
        dataUIViewModel.getRssiEmoji().observe(getViewLifecycleOwner(), resId -> rssiEmojiView.setImageResource(resId));
        dataUIViewModel.getIpText().observe(getViewLifecycleOwner(), ip -> ipTextView.setText(ip));
        dataUIViewModel.getFrequencyText().observe(getViewLifecycleOwner(), freq -> frequencyTextView.setText(freq));
        dataUIViewModel.getBandwidthText().observe(getViewLifecycleOwner(), bw -> bandwidthTextView.setText(bw));
    }
}

