package me.theoria.wifimuscles.view.fragments;

import android.graphics.Color;
import android.os.Bundle;

import androidx.fragment.app.Fragment;
import androidx.lifecycle.ViewModelProvider;

import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import com.github.mikephil.charting.charts.RadarChart;
import com.github.mikephil.charting.components.Description;
import com.github.mikephil.charting.components.XAxis;
import com.github.mikephil.charting.components.YAxis;
import com.github.mikephil.charting.data.RadarData;
import com.github.mikephil.charting.data.RadarDataSet;
import com.github.mikephil.charting.data.RadarEntry;
import com.github.mikephil.charting.formatter.ValueFormatter;

import java.util.ArrayList;
import java.util.List;

import me.theoria.wifimuscles.R;
import me.theoria.wifimuscles.data.model.WifiSignalModel;
import me.theoria.wifimuscles.utils.RSSIUtils;
import me.theoria.wifimuscles.viewmodel.WifiViewModel;


public class RadarChartFragment extends Fragment {

    // Initialize UI component objects
    private TextView rssiTextView;
    private ImageView rssiEmojiView;
    private RadarChart radarChart;

    private WifiViewModel wifiViewModel;

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container,
                             Bundle savedInstanceState) {
        View root = inflater.inflate(R.layout.fragment_radar_chart, container, false);

        // Bind UI components for the RadarChart fragment
        radarChart = root.findViewById(R.id.radarChart);
        rssiTextView = root.findViewById(R.id.rssiTextView);
        rssiEmojiView = root.findViewById(R.id.rssiEmoji);


        // Initialize the RadarChart
        setupRadarChart();

        // Initialize WifiViewModel (RSSI)
        WifiViewModel wifiViewModel = new ViewModelProvider(this,
                ViewModelProvider.AndroidViewModelFactory.getInstance(requireActivity().getApplication())).get(WifiViewModel.class);

        // Observe current SSID
        wifiViewModel.getRssiLiveData().observe(getViewLifecycleOwner(), this::updateRadarChartDescription);
        wifiViewModel.getRssiLiveData().observe(getViewLifecycleOwner(), this::updateRadarChart);

        return root;
    }

    private void updateRadarChartDescription(List<WifiSignalModel> wifiSignalModels) {
        Description description = new Description();
        description.setText("Connected to: ");
        radarChart.setDescription(description);
    }

    private void setupRadarChart() {
        // RadarChart Configuration
        radarChart.getDescription().setEnabled(false);
        radarChart.setWebColor(Color.BLACK);
        radarChart.setWebLineWidth(1f);
        radarChart.setWebColorInner(Color.LTGRAY);
        radarChart.setWebLineWidthInner(1f);

        // X Axis
        XAxis xAxis = radarChart.getXAxis();
        xAxis.setTextSize(14f);
        xAxis.setDrawLabels(true);
        xAxis.setValueFormatter(new ValueFormatter() {
            @Override
            public String getFormattedValue(float value) {
                switch ((int) value) {
                    case 5: return "Excellent";
                    case 4: return "Good";
                    case 3: return "Fair";
                    case 2: return "Weak";
                    case 1: return "Unusable";
                    default: return "";
                }
            }
        });

        // Y Axis (signal level 1-5)
        YAxis yAxis = radarChart.getYAxis();
        yAxis.setAxisMinimum(-100f);
        yAxis.setAxisMaximum(0f);
        yAxis.setLabelCount(8, true);
        yAxis.setDrawLabels(false); // hide level numbers
        yAxis.setValueFormatter(new ValueFormatter() {
            @Override
            public String getFormattedValue(float value) {
                switch ((int) value) {
                    case 5: return "Excellent";
                    case 4: return "Good";
                    case 3: return "Fair";
                    case 2: return "Weak";
                    case 1: return "Unusable";
                    default: return "";
                }
            }
        });
    }

    private void updateRadarChart(List<WifiSignalModel> signals) {
        if (signals == null || signals.isEmpty()) return;

        int count = Math.min(6, signals.size());
        int start = signals.size() - count;

        List<RadarEntry> entries = new ArrayList<>();
        List<String> radarLabels = new ArrayList<>();

        for (int i = start; i < signals.size(); i++) {
            WifiSignalModel signal = signals.get(i);

            int signalLevel = signal.getSignalLevel();
            entries.add(new RadarEntry(signalLevel));
            radarLabels.add("S" + i);
        }

        // Display RSSI integer value and emoji in TextView and ImageView
        WifiSignalModel latestSignal = signals.get(signals.size() - 1);
        int latestRssi = latestSignal.getRssi();
        rssiTextView.setText("RSSI: " + latestRssi + " dBm");
        rssiEmojiView.setImageResource(RSSIUtils.getRssiEmoji(latestRssi));

        //Show extender toast message
        //ToastUtil.showToastForLevel(requireContext(), latestSignal.getSignalLevel());

        // General UI configuration for the RadarChart datasets
        RadarDataSet dataSet = new RadarDataSet(entries, "WiFi Strength");
        dataSet.setColor(Color.BLUE);
        dataSet.setFillColor(Color.CYAN);
        dataSet.setDrawFilled(true);
        dataSet.setLineWidth(3f);
        dataSet.setValueTextColor(Color.BLACK);
        dataSet.setValueTextSize(14f);

        RadarData data = new RadarData(dataSet);
        radarChart.setData(data);
        radarChart.invalidate(); // Redraw chart
    }



}

package me.theoria.wifimuscles.viewmodel;

import android.widget.ImageView;
import android.widget.TextView;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;
import androidx.lifecycle.ViewModel;

import me.theoria.wifimuscles.data.model.WifiSignalModel;
import me.theoria.wifimuscles.utils.RSSIUtils;

import java.util.List;

public class DataUIViewModel extends ViewModel {

    private final MutableLiveData<String> rssiText = new MutableLiveData<>();
    private final MutableLiveData<Integer> rssiEmoji = new MutableLiveData<>();
    private final MutableLiveData<String> ipText = new MutableLiveData<>();
    private final MutableLiveData<String> frequencyText = new MutableLiveData<>();
    private final MutableLiveData<String> bandwidthText = new MutableLiveData<>();

    // Expose LiveData to the UI
    public LiveData<String> getRssiText() {
        return rssiText;
    }

    public LiveData<Integer> getRssiEmoji() {
        return rssiEmoji;
    }

    public LiveData<String> getIpText() {
        return ipText;
    }

    public LiveData<String> getFrequencyText() {
        return frequencyText;
    }

    public LiveData<String> getBandwidthText() {
        return bandwidthText;
    }

    // Update the LiveData based on the signal data
    public void updateSignalUI(List<WifiSignalModel> signals) {
        if (signals.isEmpty()) return;

        WifiSignalModel latestSignal = signals.get(signals.size() - 1);
        int rssi = latestSignal.getRssi();
        int ip = latestSignal.getIP();
        int frequency = latestSignal.getFrequency();

        // Update LiveData
        rssiText.setValue("RSSI: " + rssi + " dBm");
        rssiEmoji.setValue(RSSIUtils.getRssiEmoji(rssi));
        ipText.setValue("IP: " + intToIp(ip));

        String frequencyTextValue = frequency + " MHz";
        frequencyText.setValue(frequencyTextValue);

        double frequencyInGHz = frequency / 1000.0;
        String frequencyGHzText = (int) frequencyInGHz + " GHz";
        bandwidthText.setValue(frequencyGHzText);
    }

    private String intToIp(int ip) {
        return (ip & 0xFF) + "." +
                ((ip >> 8) & 0xFF) + "." +
                ((ip >> 16) & 0xFF) + "." +
                ((ip >> 24) & 0xFF);
    }
}

package me.theoria.wifimuscles.viewmodel;


import android.app.Application;
import android.net.wifi.WifiInfo;
import android.net.wifi.WifiManager;
import android.os.Handler;
import android.os.Looper;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.lifecycle.AndroidViewModel;
import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;

import me.theoria.wifimuscles.data.model.WifiSignalModel;
import me.theoria.wifimuscles.utils.RSSIUtils;

import java.util.ArrayList;
import java.util.List;

public class WifiViewModel extends AndroidViewModel {

    private final MutableLiveData<List<WifiSignalModel>> rssiLiveData = new MutableLiveData<>();
    private final List<WifiSignalModel> signalList = new ArrayList<>();
    private final WifiManager wifiManager;
    private final Handler handler = new Handler(Looper.getMainLooper());

    private final Runnable fetchRssi = new Runnable() {
        @Override
        public void run() {
            WifiInfo info = wifiManager.getConnectionInfo();
            if (info != null) {
                int rssi = info.getRssi();
                int signalLevel = RSSIUtils.mapRssiToLevels(rssi);
                long timestamp = System.currentTimeMillis();
                int frequency = info.getFrequency();
                int ip = info.getIpAddress();
                String bssid = info.getBSSID();
                int networkID = info.getNetworkId();
                //String macAddress = info.getMacAddress();

                signalList.add(new WifiSignalModel(
                        timestamp,
                        rssi,
                        signalLevel,
                        frequency,
                        ip,
                        networkID));
                if (signalList.size() > 30) {
                    signalList.remove(0);
                }

                rssiLiveData.setValue(new ArrayList<>(signalList));
            }
            handler.postDelayed(this, 2000); // ms to s
        }
    };

    public WifiViewModel(@NonNull Application application) {
        super(application);
        wifiManager = (WifiManager) application.getSystemService(Application.WIFI_SERVICE);

        if (wifiManager != null && wifiManager.isWifiEnabled()) {
            handler.post(fetchRssi);
        } else {
            Toast.makeText(application.getApplicationContext(), "Please enable Wi-Fi", Toast.LENGTH_SHORT).show();
        }
    }

    public LiveData<List<WifiSignalModel>> getRssiLiveData() {
        return rssiLiveData;
    }

    @Override
    protected void onCleared() {
        super.onCleared();
        handler.removeCallbacks(fetchRssi);
    }
}
